@font-face{ font-family:"Manrope";src:url("https://www.dgeniussolutions.com/wp-content/cache/fonts/1/google-fonts/fonts/s/manrope/v20/xn7gYHE41ni1AdIRggexSg.woff2") format("woff2");font-weight:100 900;font-style:normal;font-display:swap; }
@font-face{ font-family:"Space Grotesk";src:url("https://www.dgeniussolutions.com/wp-content/cache/fonts/1/google-fonts/fonts/s/spacegrotesk/v22/V8mDoQDjQSkFtoMM3T6r8E7mPbF4Cw.woff2") format("woff2");font-weight:300 700;font-style:normal;font-display:swap; }

.elementor-52 .elementor-element.elementor-element-7f8cb7d7:not(.elementor-motion-effects-element-type-background):not(.cmsmasters-bg-effect), .elementor-52 .elementor-element.elementor-element-7f8cb7d7 > .elementor-motion-effects-container > .elementor-motion-effects-layer, .elementor-52 .elementor-element.elementor-element-7f8cb7d7 > .cmsmasters-bg-effects-container > .cmsmasters-bg-effects-element{background-image:url("https://www.dgeniussolutions.com/wp-content/uploads/2025/06/p7bxffyqrrfg24ikyjvg-1.webp");}
/*# sourceURL=elementor-frontend-inline-css */

/* COST MODULE - URGENCY SECTION */
.bp-cost-module{position:relative;padding:180px 80px 120px;background:linear-gradient(180deg,rgba(0,0,0,0) 0%,rgba(10,0,15,.4) 100%);overflow:hidden;min-height:100vh}

.bp-cost-svg-filter{position:absolute;width:0;height:0;opacity:0;pointer-events:none}

.bp-cost-wrap{max-width:1800px;margin:0 auto;position:relative;z-index:2}

/* Header with Distortion */
.bp-cost-header{text-align:center;margin-bottom:100px;animation:bp-up .6s ease backwards}

.bp-cost-title{font-size:4.5rem;font-weight:300;line-height:1.15;color:#fff;letter-spacing:-.02em;margin:0}

.bp-cost-title-highlight{display:block;background:linear-gradient(90deg,#ff4655 0%,#ff8a00 25%,#ffd700 50%,#ff4655 100%);background-size:200% auto;-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;font-weight:400;animation:bp-flow 8s linear infinite}

/* Distortion on Scroll */
.bp-cost-title[data-distort]{transition:filter .3s ease}

.bp-cost-module.is-scrolling .bp-cost-title[data-distort]{filter:url(#bpBreakApart);animation:bp-shake .5s ease}

/* Horizontal Scroll Container */
.bp-cost-scroll-container{position:relative;overflow-x:auto;overflow-y:hidden;padding:60px 0;margin-bottom:80px;cursor:grab;-webkit-overflow-scrolling:touch;scrollbar-width:none}

.bp-cost-scroll-container::-webkit-scrollbar{display:none}

.bp-cost-scroll-container:active{cursor:grabbing}

.bp-cost-scroll-track{display:flex;gap:40px;padding:0 80px;width:max-content}

/* Cost Cards */
.bp-cost-card{flex:0 0 480px;height:auto;background:rgba(15,15,25,.6);border:1px solid rgba(255,255,255,.08);border-radius:16px;backdrop-filter:blur(20px);transition:all .4s cubic-bezier(.4,0,.2,1);position:relative;overflow:hidden}

.bp-cost-card::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,rgba(255,70,85,.4),transparent);opacity:0;transition:opacity .4s ease}

.bp-cost-card:hover{transform:translateY(-12px);border-color:rgba(255,70,85,.3);box-shadow:0 30px 80px rgba(255,70,85,.15),0 0 0 1px rgba(255,70,85,.1)}

.bp-cost-card:hover::before{opacity:1}

.bp-cost-card-inner{padding:50px 40px}

/* Card Icon */
.bp-cost-card-icon{margin-bottom:30px;color:rgba(255,70,85,.6);opacity:.8}

/* Card Label */
.bp-cost-card-label{font-size:.85rem;font-weight:500;text-transform:uppercase;letter-spacing:.15em;color:rgba(255,70,85,.7);margin-bottom:20px}

/* Card Title */
.bp-cost-card-title{font-size:2rem;font-weight:400;color:#fff;margin-bottom:25px;line-height:1.3}

/* Card Copy */
.bp-cost-card-copy{font-size:1.075rem;font-weight:300;line-height:1.8;color:rgba(255,255,255,.6);margin-bottom:35px}

.bp-cost-card-copy strong{color:rgba(255,255,255,.9);font-weight:500}

/* Card Stat */
.bp-cost-card-stat{padding-top:30px;border-top:1px solid rgba(255,255,255,.08)}

.bp-cost-stat-number{font-size:3rem;font-weight:600;background:linear-gradient(135deg,#ff4655,#ff8a00);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;margin-bottom:8px;line-height:1}

.bp-cost-stat-label{font-size:.95rem;font-weight:300;color:rgba(255,255,255,.5);letter-spacing:.05em}

/* Scroll Hint */
.bp-cost-scroll-hint{display:flex;align-items:center;gap:15px;justify-content:center;color:rgba(255,255,255,.4);font-size:1rem;font-weight:300;margin-bottom:80px;animation:bp-pulse 2s ease-in-out infinite}

.bp-cost-scroll-hint svg{opacity:.6}

/* CTA Section - MUCH BRIGHTER */
.bp-cost-cta-section{text-align:center;padding:80px 40px;background:linear-gradient(135deg,rgba(255,70,85,.15),rgba(255,138,0,.15));border-radius:20px;border:1px solid rgba(255,70,85,.3);backdrop-filter:blur(10px)}

.bp-cost-cta-text{font-size:1.75rem;font-weight:300;color:rgba(255,255,255,.95);margin-bottom:40px;line-height:1.5}

/* BRIGHT GLOWING CTA BUTTON */
.bp-cost-cta-btn{display:inline-flex;align-items:center;gap:15px;font-size:1.25rem;font-weight:600;color:#fff;text-decoration:none;padding:22px 50px;border-radius:10px;background:linear-gradient(135deg,#ff4655,#ff8a00);border:none;transition:all .4s ease;letter-spacing:.02em;position:relative;overflow:hidden;box-shadow:0 10px 40px rgba(255,70,85,.5),0 0 20px rgba(255,138,0,.3),0 0 0 1px rgba(255,255,255,.1) inset}

.bp-cost-cta-btn::before{content:'';position:absolute;inset:0;background:linear-gradient(135deg,#ff8a00,#ffd700);opacity:0;transition:opacity .4s ease}

.bp-cost-cta-btn::after{content:'';position:absolute;top:-50%;left:-50%;width:200%;height:200%;background:linear-gradient(45deg,transparent,rgba(255,255,255,.2),transparent);transform:rotate(45deg);transition:all .6s ease}

.bp-cost-cta-btn svg{transition:transform .4s ease;position:relative;z-index:2}

.bp-cost-cta-btn span{position:relative;z-index:2}

.bp-cost-cta-btn:hover{gap:22px;transform:translateY(-5px) scale(1.02);box-shadow:0 25px 70px rgba(255,70,85,.7),0 0 40px rgba(255,138,0,.5),0 0 60px rgba(255,70,85,.3),0 0 0 2px rgba(255,255,255,.2) inset}

.bp-cost-cta-btn:hover::before{opacity:1}

.bp-cost-cta-btn:hover::after{left:100%}

.bp-cost-cta-btn:hover svg{transform:translateX(5px)}

/* Pulsing Glow Animation */
@keyframes bp-cta-glow{
  0%,100%{box-shadow:0 10px 40px rgba(255,70,85,.5),0 0 20px rgba(255,138,0,.3),0 0 0 1px rgba(255,255,255,.1) inset}
  50%{box-shadow:0 15px 50px rgba(255,70,85,.7),0 0 30px rgba(255,138,0,.5),0 0 40px rgba(255,70,85,.3),0 0 0 1px rgba(255,255,255,.15) inset}
}

.bp-cost-cta-btn{animation:bp-cta-glow 3s ease-in-out infinite}

/* Animations */
@keyframes bp-shake{
  0%,100%{transform:translateX(0)}
  25%{transform:translateX(-5px)}
  75%{transform:translateX(5px)}
}

@keyframes bp-pulse{
  0%,100%{opacity:.4;transform:translateX(0)}
  50%{opacity:.7;transform:translateX(10px)}
}

@keyframes bp-up{
  from{opacity:0;transform:translateY(40px)}
  to{opacity:1;transform:translateY(0)}
}

@keyframes bp-flow{
  0%{background-position:0% 50%}
  50%{background-position:100% 50%}
  100%{background-position:0% 50%}
}

/* Responsive */
@media (max-width:1200px){
  .bp-cost-module{padding:150px 60px 100px}
  .bp-cost-title{font-size:3.5rem}
  .bp-cost-card{flex:0 0 420px}
}

@media (max-width:900px){
  .bp-cost-module{padding:120px 40px 80px}
  .bp-cost-title{font-size:2.75rem}
  .bp-cost-scroll-track{padding:0 40px}
  .bp-cost-card{flex:0 0 360px}
  .bp-cost-card-inner{padding:40px 30px}
}

@media (max-width:600px){
  .bp-cost-module{padding:100px 24px 60px}
  .bp-cost-title{font-size:2rem}
  .bp-cost-scroll-track{padding:0 24px}
  .bp-cost-card{flex:0 0 300px}
  .bp-cost-card-title{font-size:1.5rem}
  .bp-cost-card-copy{font-size:1rem}
  .bp-cost-cta-text{font-size:1.25rem}
  .bp-cost-cta-btn{width:100%;justify-content:center;padding:20px 40px}
}

/* CRITICAL CSS - Mobile First */
body{background:#000;overflow-x:hidden}
.bp-wrap{position:relative;min-height:100vh;background:#000;overflow:hidden}
.bp-wrap *{box-sizing:border-box}

/* MOBILE OPTIMIZED GRADIENT */
.bp-bg-gradient{
  position:fixed;
  top:0;
  left:0;
  width:100%;
  height:100%;
  z-index:0;
  opacity:.3;
  background:radial-gradient(circle at 20% 30%,rgba(0,212,255,.25) 0%,transparent 50%),radial-gradient(circle at 80% 70%,rgba(241,7,163,.2) 0%,transparent 50%);
  pointer-events:none;
}

@media (min-width:769px){
  .bp-bg-gradient{
    animation:bp-bg-shift 20s ease-in-out 2s infinite;
    will-change:transform;
    transform:translateZ(0);
  }
}

@keyframes bp-bg-shift{
  0%,100%{transform:scale(1) rotate(0deg)}
  50%{transform:scale(1.1) rotate(10deg)}
}

/* Hero */
.bp-hero{
  position:relative;
  z-index:2;
  min-height:100vh;
  display:flex;
  align-items:center;
  padding:120px 16px 60px;
  background:transparent;
}

@media (min-width:769px){
  .bp-hero{
    padding:180px 80px 120px;
    opacity:0;
    animation:bp-fade-in .8s ease .2s forwards;
  }
}

@keyframes bp-fade-in{to{opacity:1}}

.bp-hero-wrap{
  max-width:1500px;
  margin:0 auto;
  width:100%;
}

/* Typography */
.bp-eyebrow{
  font-size:.7rem;
  font-weight:500;
  letter-spacing:.25em;
  color:rgba(255,255,255,.7);
  margin-bottom:30px;
}

.bp-title{
  margin:0 0 50px;
  line-height:1.1;
}

/* Text Lines */
.bp-t-line{
  display:block;
  font-size:2rem;
  font-weight:300;
  letter-spacing:.03em;
  color:#fff;
  margin-bottom:12px;
}

@media (min-width:769px){
  .bp-eyebrow{
    font-size:.75rem;
    margin-bottom:60px;
  }
  .bp-title{
    margin:0 0 80px;
    line-height:1;
  }
  .bp-t-line{
    font-size:6rem;
    letter-spacing:.05em;
    margin-bottom:20px;
    animation:bp-up .7s ease backwards;
    will-change:transform,opacity;
  }
  .bp-t-line:nth-child(1){animation-delay:.4s}
  .bp-t-line:nth-child(2){animation-delay:.5s}
  .bp-t-line:nth-child(3){animation-delay:.6s}
}

@keyframes bp-up{
  from{opacity:0;transform:translate3d(0,20px,0)}
  to{opacity:1;transform:translate3d(0,0,0)}
}

/* GRADIENT TEXT - MOBILE USES SOLID COLOR */
.bp-t-grad{
  color:#00d4ff;
}

@media (min-width:769px){
  .bp-t-grad{
    color:transparent;
    background:linear-gradient(90deg,#00d4ff 0%,#7b2ff7 25%,#f107a3 50%,#fd8200 75%,#ffed00 100%);
    background-size:200% auto;
    -webkit-background-clip:text;
    -webkit-text-fill-color:transparent;
    background-clip:text;
    animation:bp-up .7s ease .6s backwards,bp-flow 8s linear infinite;
    will-change:background-position;
  }
}

@keyframes bp-flow{to{background-position:200% center}}

.bp-subtitle{
  font-size:1rem;
  font-weight:400;
  line-height:1.6;
  color:#fff;
  margin:0 0 50px;
  max-width:1000px;
}

@media (min-width:769px){
  .bp-subtitle{
    font-size:1.5rem;
    line-height:1.7;
    margin:0 0 100px;
    animation:bp-up .6s ease .8s backwards;
  }
}

/* Stats */
.bp-stats{
  display:flex;
  flex-direction:column;
  gap:30px;
  margin-bottom:50px;
}

@media (min-width:769px){
  .bp-stats{
    flex-direction:row;
    gap:100px;
    margin-bottom:100px;
    flex-wrap:wrap;
    animation:bp-up .6s ease .9s backwards;
  }
}

.bp-stat{
  display:flex;
  flex-direction:column;
  gap:15px;
}

.bp-stat-num{
  font-size:2.5rem;
  font-weight:300;
  color:#fff;
  line-height:1;
  letter-spacing:-.02em;
}

@media (min-width:769px){
  .bp-stat-num{font-size:4.5rem}
}

.bp-stat-s{
  font-size:1.8rem;
  font-weight:300;
  color:rgba(255,255,255,.7);
}

@media (min-width:769px){
  .bp-stat-s{font-size:3rem}
}

.bp-stat-line{
  width:100%;
  height:2px;
  background:linear-gradient(90deg,#00d4ff,#7b2ff7);
  border-radius:50px;
}

@media (min-width:769px){
  .bp-stat-line{
    height:3px;
    box-shadow:0 0 15px rgba(0,212,255,.4);
  }
}

.bp-stat-label{
  font-size:.7rem;
  color:rgba(255,255,255,.7);
  text-transform:uppercase;
  letter-spacing:.12em;
  font-weight:500;
}

@media (min-width:769px){
  .bp-stat-label{
    font-size:.75rem;
    letter-spacing:.15em;
  }
}

/* Buttons */
.bp-cta{
  display:flex;
  flex-direction:column;
  gap:16px;
  width:100%;
}

@media (min-width:769px){
  .bp-cta{
    flex-direction:row;
    gap:32px;
    width:auto;
    flex-wrap:wrap;
    animation:bp-up .6s ease 1s backwards;
  }
}

.bp-btn-pri{
  padding:16px 40px;
  background:transparent;
  color:#fff;
  text-decoration:none;
  font-size:1rem;
  font-weight:500;
  letter-spacing:.03em;
  border:2px solid rgba(255,255,255,.4);
  border-radius:8px;
  display:block;
  text-align:center;
  cursor:pointer;
  transition:border-color .3s ease;
}

@media (min-width:769px){
  .bp-btn-pri{
    position:relative;
    padding:18px 50px;
    letter-spacing:.05em;
    overflow:hidden;
    display:inline-block;
    backdrop-filter:blur(10px);
    transition:all .4s cubic-bezier(.4,0,.2,1);
    will-change:transform;
  }
  .bp-btn-pri::before{
    content:'';
    position:absolute;
    inset:0;
    background:linear-gradient(135deg,rgba(241,7,163,.15),rgba(123,47,247,.15));
    z-index:-1;
    transition:background .4s ease;
  }
  .bp-btn-pri:hover{
    border-color:#00d4ff;
    transform:translate3d(0,-3px,0);
    box-shadow:0 10px 30px rgba(0,212,255,.3);
  }
  .bp-btn-pri:hover::before{
    background:linear-gradient(135deg,rgba(241,7,163,.3),rgba(123,47,247,.3));
  }
}

.bp-btn-sec{
  padding:16px 40px;
  background:transparent;
  color:rgba(255,255,255,.9);
  text-decoration:none;
  font-size:1rem;
  font-weight:400;
  letter-spacing:.03em;
  border:2px solid rgba(255,255,255,.25);
  border-radius:8px;
  display:block;
  text-align:center;
  cursor:pointer;
  transition:border-color .3s ease;
}

@media (min-width:769px){
  .bp-btn-sec{
    position:relative;
    padding:18px 50px;
    letter-spacing:.05em;
    display:inline-block;
    backdrop-filter:blur(10px);
    transition:all .3s cubic-bezier(.4,0,.2,1);
    will-change:transform;
  }
  .bp-btn-sec:hover{
    color:#fff;
    border-color:rgba(255,255,255,.5);
    transform:translate3d(0,-3px,0);
    box-shadow:0 8px 20px rgba(255,255,255,.1);
  }
}

/* Content Visibility */
.bp-premium-module,
.bp-contact-module{
  content-visibility:auto;
  contain-intrinsic-size:0 500px;
}

/* Tablet */
@media (min-width:481px) and (max-width:768px){
  .bp-hero{padding:140px 24px 80px}
  .bp-t-line{font-size:2.5rem;margin-bottom:15px}
  .bp-subtitle{font-size:1.125rem;margin-bottom:60px}
  .bp-stats{gap:40px;margin-bottom:60px}
  .bp-stat-num{font-size:3rem}
  .bp-stat-s{font-size:2rem}
}

/* Desktop */
@media (min-width:1025px){
  .bp-t-line{font-size:4.5rem}
  .bp-stats{gap:60px}
  .bp-hero{padding:160px 60px 100px}
}

@media (min-width:1400px){
  .bp-t-line{font-size:6rem}
}

/* Reduce Motion */
@media (prefers-reduced-motion:reduce){
  *,::before,::after{
    animation-duration:.01ms!important;
    animation-iteration-count:1!important;
    transition-duration:.01ms!important;
  }
  .bp-bg-gradient{animation:none}
}

/* STATS MODULE - TRANSPARENT BACKGROUND */
.bp-stats-module{position:relative;z-index:2;padding:150px 80px;background:transparent;min-height:100vh;display:flex;align-items:center}
.bp-sm-wrap{max-width:1500px;margin:0 auto;width:100%}

/* Content Section (Now First) */
.bp-sm-content{text-align:center;max-width:1200px;margin:0 auto 120px auto;animation:bp-up .6s ease backwards}
.bp-sm-title{margin-bottom:50px;line-height:1.2;margin-top:0}
.bp-sm-t-line{display:block;font-size:4rem;font-weight:300;letter-spacing:.02em;color:#fff;margin-bottom:15px}
.bp-sm-t-grad{background:linear-gradient(90deg,#00d4ff 0%,#7b2ff7 25%,#f107a3 50%,#fd8200 75%,#ffed00 100%);background-size:200% auto;-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;animation:bp-flow 8s linear infinite}

/* Body Text */
.bp-sm-body{font-size:1.25rem;font-weight:300;line-height:1.8;color:rgba(255,255,255,.8)}
.bp-sm-body p{margin:0 0 25px 0}
.bp-sm-body p:last-child{margin-bottom:0}

/* Stats Grid 2x2 */
.bp-sm-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:40px;animation:bp-up .6s ease .3s backwards}

/* Stat Cards - Glass Effect */
.bp-sm-card{background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.1);border-radius:20px;padding:50px 40px;transition:all .5s ease;backdrop-filter:blur(10px);position:relative;overflow:hidden}
.bp-sm-card::before{content:'';position:absolute;top:0;left:0;width:100%;height:100%;background:linear-gradient(135deg,rgba(0,212,255,.05),rgba(241,7,163,.05));opacity:0;transition:opacity .5s ease}
.bp-sm-card:hover{transform:translateY(-10px);border-color:rgba(0,212,255,.4);box-shadow:0 25px 80px rgba(0,212,255,.2)}
.bp-sm-card:hover::before{opacity:1}

/* Number Display */
.bp-sm-number{display:flex;align-items:baseline;margin-bottom:25px;font-weight:200;line-height:1}
.bp-sm-prefix{font-size:4rem;color:rgba(255,255,255,.6);margin-right:5px}
.bp-sm-num{font-size:6rem;background:linear-gradient(90deg,#00d4ff 0%,#7b2ff7 50%,#f107a3 100%);background-size:200% auto;-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;animation:bp-flow 8s linear infinite}
.bp-sm-symbol{font-size:4rem;color:rgba(255,255,255,.6);margin-left:5px}

/* Labels */
.bp-sm-label{font-size:1.5rem;font-weight:400;color:#fff;margin-bottom:15px;letter-spacing:.02em}
.bp-sm-desc{font-size:1rem;font-weight:300;color:rgba(255,255,255,.6);margin:0;line-height:1.6}

/* Responsive */
@media (max-width:1024px){
  .bp-stats-module{padding:120px 60px}
  .bp-sm-content{margin-bottom:80px}
  .bp-sm-num{font-size:5rem}
  .bp-sm-prefix,.bp-sm-symbol{font-size:3.5rem}
  .bp-sm-label{font-size:1.25rem}
  .bp-sm-t-line{font-size:3rem}
  .bp-sm-body{font-size:1.125rem}
}
@media (max-width:768px){
  .bp-stats-module{padding:100px 24px}
  .bp-sm-content{margin-bottom:60px}
  .bp-sm-grid{grid-template-columns:1fr;gap:30px}
  .bp-sm-card{padding:40px 30px}
  .bp-sm-num{font-size:4rem}
  .bp-sm-prefix,.bp-sm-symbol{font-size:2.5rem}
  .bp-sm-label{font-size:1.125rem}
  .bp-sm-t-line{font-size:2rem}
  .bp-sm-body{font-size:1rem}
}

/* ========== AGGRESSIVE CSS RESET ========== */
.bp-premium-module, .bp-premium-module *, .bp-premium-module *::before, .bp-premium-module *::after {
  box-sizing: border-box !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  outline: none !important;
  text-decoration: none !important;
  list-style: none !important;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif !important;
  -webkit-font-smoothing: antialiased !important;
  -moz-osx-font-smoothing: grayscale !important;
}

/* ========== DOWNLOAD PROTECTION ========== */
.bp-premium-module img,
.bp-premium-module video,
#bpImageFrame,
#bpVideoFrame {
  user-select: none !important;
  -webkit-user-select: none !important;
  -moz-user-select: none !important;
  -ms-user-select: none !important;
  pointer-events: auto !important;
  -webkit-user-drag: none !important;
  -khtml-user-drag: none !important;
  -moz-user-drag: none !important;
