  transition: all .4s ease !important;
  letter-spacing: .02em !important;
  border: 1px solid rgba(255,255,255,.15) !important;
  cursor: pointer !important;
}

.bp-pm-cta-btn::before {
  content: '' !important;
  position: absolute !important;
  inset: 0 !important;
  background: linear-gradient(135deg, rgba(0,212,255,.15), rgba(241,7,163,.15)) !important;
  transition: all .4s ease !important;
  z-index: -1 !important;
  display: block !important;
}

.bp-pm-cta-btn svg {
  transition: transform .4s ease !important;
  display: inline-block !important;
  stroke: currentColor !important;
  fill: none !important;
}

.bp-pm-cta-btn span {
  display: inline-block !important;
}

.bp-pm-cta-btn:hover {
  gap: 20px !important;
  border-color: rgba(255,255,255,.3) !important;
  transform: translateY(-3px) !important;
  box-shadow: 0 15px 40px rgba(0,212,255,.2), 0 15px 40px rgba(241,7,163,.2) !important;
}

.bp-pm-cta-btn:hover::before {
  background: linear-gradient(135deg, rgba(0,212,255,.25), rgba(241,7,163,.25)) !important;
}

.bp-pm-cta-btn:hover svg {
  transform: translateX(5px) !important;
}

.bp-pm-gallery-grid {
  display: grid !important;
  grid-template-columns: repeat(2, 1fr) !important;
  gap: 20px !important;
  grid-auto-rows: 240px !important;
}

.bp-pm-gallery-item {
  position: relative !important;
  overflow: hidden !important;
  border-radius: 8px !important;
  cursor: pointer !important;
  display: block !important;
}

.bp-pm-gallery-item.bp-pm-large {
  grid-column: span 2 !important;
  grid-row: span 2 !important;
}

.bp-pm-img-wrap {
  width: 100% !important;
  height: 100% !important;
  position: relative !important;
  overflow: hidden !important;
  background: rgba(0,0,0,.4) !important;
  transition: all .5s cubic-bezier(.4,0,.2,1) !important;
  display: block !important;
}

.bp-pm-gallery-item:hover .bp-pm-img-wrap {
  transform: scale(1.02) !important;
}

.bp-pm-gallery-item::before {
  content: '' !important;
  position: absolute !important;
  inset: 0 !important;
  background: linear-gradient(135deg, rgba(0,212,255,0), rgba(241,7,163,0)) !important;
  opacity: 0 !important;
  transition: opacity .5s ease !important;
  z-index: 1 !important;
  pointer-events: none !important;
  display: block !important;
}

.bp-pm-gallery-item:hover::before {
  opacity: .2 !important;
  background: linear-gradient(135deg, rgba(0,212,255,.4), rgba(123,47,247,.3), rgba(241,7,163,.4)) !important;
}

.bp-pm-gallery-item::after {
  content: '' !important;
  position: absolute !important;
  inset: 0 !important;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.06) !important;
  border-radius: 8px !important;
  transition: all .5s ease !important;
  pointer-events: none !important;
  display: block !important;
}

.bp-pm-gallery-item:hover::after {
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.12), 0 30px 90px -15px rgba(0,212,255,.3), 0 30px 90px -15px rgba(241,7,163,.3) !important;
}

.bp-pm-img-wrap img,
.bp-pm-img-wrap video {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  display: block !important;
  user-select: none !important;
}

/* ========== GALLERY ITEM LABELS ========== */
.bp-pm-label {
  position: absolute !important;
  bottom: 0 !important;
  left: 0 !important;
  right: 0 !important;
  padding: 12px 16px !important;
  background: linear-gradient(to top, rgba(0,0,0,.85) 0%, rgba(0,0,0,.6) 60%, transparent 100%) !important;
  color: #ffffff !important;
  font-size: .875rem !important;
  font-weight: 500 !important;
  letter-spacing: .05em !important;
  opacity: 0 !important;
  transform: translateY(10px) !important;
  transition: all .4s ease !important;
  z-index: 3 !important;
  pointer-events: none !important;
  display: block !important;
  text-align: center !important;
}

.bp-pm-gallery-item:hover .bp-pm-label {
  opacity: 1 !important;
  transform: translateY(0) !important;
}

.bp-pm-file-overlay {
  position: absolute !important;
  top: 12px !important;
  right: 12px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: flex-end !important;
  z-index: 2 !important;
  pointer-events: none !important;
}

.bp-pm-file-badge {
  color: #fff !important;
  padding: 8px 14px !important;
  border-radius: 6px !important;
  font-size: .8rem !important;
  font-weight: 600 !important;
  letter-spacing: .08em !important;
  display: block !important;
  box-shadow: 0 4px 15px rgba(0,0,0,.3) !important;
  border: 1px solid rgba(255,255,255,.2) !important;
  transition: all .3s ease !important;
}

.bp-pm-ppt-badge {
  background: rgba(253,130,0,.9) !important;
}

.bp-pm-pdf-badge {
  background: rgba(241,7,163,.9) !important;
}

.bp-pm-video-badge {
  background: rgba(123,47,247,.9) !important;
}

.bp-pm-gallery-item:hover .bp-pm-file-badge {
  transform: scale(1.05) !important;
  box-shadow: 0 6px 20px rgba(0,0,0,.5) !important;
}

@keyframes bp-fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes bp-slide-up {
  from {
    opacity: 0;
    transform: translateY(60px) scale(0.95);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes bp-up {
  from { opacity: 0; transform: translateY(40px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes bp-flow {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

