/* COST MODULE - URGENCY SECTION */
.bp-cost-module{position:relative;padding:180px 80px 120px;background:linear-gradient(180deg,rgba(0,0,0,0) 0%,rgba(10,0,15,.4) 100%);overflow:hidden;min-height:100vh}

.bp-cost-svg-filter{position:absolute;width:0;height:0;opacity:0;pointer-events:none}

.bp-cost-wrap{max-width:1800px;margin:0 auto;position:relative;z-index:2}

/* Header with Distortion */
.bp-cost-header{text-align:center;margin-bottom:100px;animation:bp-up .6s ease backwards}

.bp-cost-title{font-size:4.5rem;font-weight:300;line-height:1.15;color:#fff;letter-spacing:-.02em;margin:0}

.bp-cost-title-highlight{display:block;background:linear-gradient(90deg,#ff4655 0%,#ff8a00 25%,#ffd700 50%,#ff4655 100%);background-size:200% auto;-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;font-weight:400;animation:bp-flow 8s linear infinite}

/* Distortion on Scroll */
.bp-cost-title[data-distort]{transition:filter .3s ease}

.bp-cost-module.is-scrolling .bp-cost-title[data-distort]{filter:url(#bpBreakApart);animation:bp-shake .5s ease}

/* Horizontal Scroll Container */
.bp-cost-scroll-container{position:relative;overflow-x:auto;overflow-y:hidden;padding:60px 0;margin-bottom:80px;cursor:grab;-webkit-overflow-scrolling:touch;scrollbar-width:none}

.bp-cost-scroll-container::-webkit-scrollbar{display:none}

.bp-cost-scroll-container:active{cursor:grabbing}

.bp-cost-scroll-track{display:flex;gap:40px;padding:0 80px;width:max-content}

/* Cost Cards */
.bp-cost-card{flex:0 0 480px;height:auto;background:rgba(15,15,25,.6);border:1px solid rgba(255,255,255,.08);border-radius:16px;backdrop-filter:blur(20px);transition:all .4s cubic-bezier(.4,0,.2,1);position:relative;overflow:hidden}

.bp-cost-card::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,rgba(255,70,85,.4),transparent);opacity:0;transition:opacity .4s ease}

.bp-cost-card:hover{transform:translateY(-12px);border-color:rgba(255,70,85,.3);box-shadow:0 30px 80px rgba(255,70,85,.15),0 0 0 1px rgba(255,70,85,.1)}

.bp-cost-card:hover::before{opacity:1}

.bp-cost-card-inner{padding:50px 40px}

/* Card Icon */
.bp-cost-card-icon{margin-bottom:30px;color:rgba(255,70,85,.6);opacity:.8}

/* Card Label */
.bp-cost-card-label{font-size:.85rem;font-weight:500;text-transform:uppercase;letter-spacing:.15em;color:rgba(255,70,85,.7);margin-bottom:20px}

/* Card Title */
.bp-cost-card-title{font-size:2rem;font-weight:400;color:#fff;margin-bottom:25px;line-height:1.3}

/* Card Copy */
.bp-cost-card-copy{font-size:1.075rem;font-weight:300;line-height:1.8;color:rgba(255,255,255,.6);margin-bottom:35px}

.bp-cost-card-copy strong{color:rgba(255,255,255,.9);font-weight:500}

/* Card Stat */
.bp-cost-card-stat{padding-top:30px;border-top:1px solid rgba(255,255,255,.08)}

.bp-cost-stat-number{font-size:3rem;font-weight:600;background:linear-gradient(135deg,#ff4655,#ff8a00);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;margin-bottom:8px;line-height:1}

.bp-cost-stat-label{font-size:.95rem;font-weight:300;color:rgba(255,255,255,.5);letter-spacing:.05em}

/* Scroll Hint */
.bp-cost-scroll-hint{display:flex;align-items:center;gap:15px;justify-content:center;color:rgba(255,255,255,.4);font-size:1rem;font-weight:300;margin-bottom:80px;animation:bp-pulse 2s ease-in-out infinite}

.bp-cost-scroll-hint svg{opacity:.6}

/* CTA Section - MUCH BRIGHTER */
.bp-cost-cta-section{text-align:center;padding:80px 40px;background:linear-gradient(135deg,rgba(255,70,85,.15),rgba(255,138,0,.15));border-radius:20px;border:1px solid rgba(255,70,85,.3);backdrop-filter:blur(10px)}

.bp-cost-cta-text{font-size:1.75rem;font-weight:300;color:rgba(255,255,255,.95);margin-bottom:40px;line-height:1.5}

/* BRIGHT GLOWING CTA BUTTON */
.bp-cost-cta-btn{display:inline-flex;align-items:center;gap:15px;font-size:1.25rem;font-weight:600;color:#fff;text-decoration:none;padding:22px 50px;border-radius:10px;background:linear-gradient(135deg,#ff4655,#ff8a00);border:none;transition:all .4s ease;letter-spacing:.02em;position:relative;overflow:hidden;box-shadow:0 10px 40px rgba(255,70,85,.5),0 0 20px rgba(255,138,0,.3),0 0 0 1px rgba(255,255,255,.1) inset}

.bp-cost-cta-btn::before{content:'';position:absolute;inset:0;background:linear-gradient(135deg,#ff8a00,#ffd700);opacity:0;transition:opacity .4s ease}

.bp-cost-cta-btn::after{content:'';position:absolute;top:-50%;left:-50%;width:200%;height:200%;background:linear-gradient(45deg,transparent,rgba(255,255,255,.2),transparent);transform:rotate(45deg);transition:all .6s ease}

.bp-cost-cta-btn svg{transition:transform .4s ease;position:relative;z-index:2}

.bp-cost-cta-btn span{position:relative;z-index:2}

.bp-cost-cta-btn:hover{gap:22px;transform:translateY(-5px) scale(1.02);box-shadow:0 25px 70px rgba(255,70,85,.7),0 0 40px rgba(255,138,0,.5),0 0 60px rgba(255,70,85,.3),0 0 0 2px rgba(255,255,255,.2) inset}

.bp-cost-cta-btn:hover::before{opacity:1}

.bp-cost-cta-btn:hover::after{left:100%}

.bp-cost-cta-btn:hover svg{transform:translateX(5px)}

/* Pulsing Glow Animation */
@keyframes bp-cta-glow{
  0%,100%{box-shadow:0 10px 40px rgba(255,70,85,.5),0 0 20px rgba(255,138,0,.3),0 0 0 1px rgba(255,255,255,.1) inset}
  50%{box-shadow:0 15px 50px rgba(255,70,85,.7),0 0 30px rgba(255,138,0,.5),0 0 40px rgba(255,70,85,.3),0 0 0 1px rgba(255,255,255,.15) inset}
}

.bp-cost-cta-btn{animation:bp-cta-glow 3s ease-in-out infinite}

/* Animations */
@keyframes bp-shake{
  0%,100%{transform:translateX(0)}
  25%{transform:translateX(-5px)}
  75%{transform:translateX(5px)}
}

@keyframes bp-pulse{
  0%,100%{opacity:.4;transform:translateX(0)}
  50%{opacity:.7;transform:translateX(10px)}
}

@keyframes bp-up{
  from{opacity:0;transform:translateY(40px)}
  to{opacity:1;transform:translateY(0)}
}

@keyframes bp-flow{
  0%{background-position:0% 50%}
  50%{background-position:100% 50%}
  100%{background-position:0% 50%}
}

/* Responsive */
@media (max-width:1200px){
  .bp-cost-module{padding:150px 60px 100px}
  .bp-cost-title{font-size:3.5rem}
  .bp-cost-card{flex:0 0 420px}
}

@media (max-width:900px){
  .bp-cost-module{padding:120px 40px 80px}
  .bp-cost-title{font-size:2.75rem}
  .bp-cost-scroll-track{padding:0 40px}
  .bp-cost-card{flex:0 0 360px}
  .bp-cost-card-inner{padding:40px 30px}
}

@media (max-width:600px){
  .bp-cost-module{padding:100px 24px 60px}
  .bp-cost-title{font-size:2rem}
  .bp-cost-scroll-track{padding:0 24px}
  .bp-cost-card{flex:0 0 300px}
  .bp-cost-card-title{font-size:1.5rem}
  .bp-cost-card-copy{font-size:1rem}
  .bp-cost-cta-text{font-size:1.25rem}
  .bp-cost-cta-btn{width:100%;justify-content:center;padding:20px 40px}
}

/* TRENDS MODULE - CALM + VIBRANT */
.bp-trends-module{position:relative;padding:200px 80px 150px;background:transparent!important;overflow:visible;min-height:100vh}

/* Subtle Ambient Background */
.bp-ambient-bg{position:fixed;inset:0;z-index:0;overflow:hidden;pointer-events:none}

.bp-gradient-orb{position:absolute;border-radius:50%;filter:blur(120px);opacity:.15;animation:bp-float-orb 20s ease-in-out infinite}

.bp-orb-1{width:600px;height:600px;background:radial-gradient(circle,rgba(0,212,255,.8),transparent 70%);top:10%;left:10%;animation-delay:0s}

.bp-orb-2{width:500px;height:500px;background:radial-gradient(circle,rgba(123,47,247,.8),transparent 70%);top:60%;right:15%;animation-delay:-7s}

.bp-orb-3{width:550px;height:550px;background:radial-gradient(circle,rgba(241,7,163,.8),transparent 70%);bottom:10%;left:50%;animation-delay:-14s}

.bp-gradient-mesh{position:absolute;inset:0;background:radial-gradient(circle at 30% 40%,rgba(0,212,255,.03),transparent 50%),radial-gradient(circle at 70% 60%,rgba(123,47,247,.03),transparent 50%);opacity:.6}

.bp-trends-wrap{max-width:1600px;margin:0 auto;position:relative;z-index:2}

/* Hero Header */
.bp-trends-hero{text-align:center;margin-bottom:120px;animation:bp-fade-in 1s ease backwards}

.bp-hero-label{font-size:1rem;font-weight:600;text-transform:uppercase;letter-spacing:.25em;background:linear-gradient(90deg,#00d4ff,#00f5a0);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;margin-bottom:30px}

.bp-hero-title{margin:0 0 35px;line-height:1}

.bp-title-year{display:block;font-size:8rem;font-weight:800;background:linear-gradient(135deg,rgba(255,255,255,.15),rgba(255,255,255,.05));-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;letter-spacing:-.05em;margin-bottom:10px}

.bp-title-main{display:block;font-size:4.5rem;font-weight:700;color:#fff;letter-spacing:-.02em}

.bp-hero-desc{font-size:1.35rem;font-weight:300;color:rgba(255,255,255,.7);max-width:850px;margin:0 auto;line-height:1.75}

/* Trends Showcase - VIBRANT CARDS */
.bp-trends-showcase{display:grid;grid-template-columns:repeat(2,1fr);gap:40px;margin-bottom:120px}

/* Trend Cards - PREMIUM GRADIENTS */
.bp-trend-card{position:relative;border-radius:32px;overflow:hidden;transition:all .6s cubic-bezier(.34,1.56,.64,1);cursor:pointer;animation:bp-fade-up .8s ease backwards;animation-delay:calc(var(--index) * 0.1s)}

.bp-trend-card:nth-child(1){--index:1}
.bp-trend-card:nth-child(2){--index:2}
.bp-trend-card:nth-child(3){--index:3}
.bp-trend-card:nth-child(4){--index:4}
.bp-trend-card:nth-child(5){--index:5}
.bp-trend-card:nth-child(6){--index:6}

/* Card Background Layer */
.bp-card-bg{position:absolute;inset:0;z-index:0;transition:all .6s ease}

.bp-card-gradient{position:absolute;inset:0;opacity:1;transition:opacity .6s ease}

/* Gradient Backgrounds - VIBRANT COLORS */
.bp-card-cyan .bp-card-gradient{background:linear-gradient(135deg,rgba(0,212,255,.25) 0%,rgba(0,180,220,.15) 50%,rgba(15,20,35,.95) 100%)}
.bp-card-purple .bp-card-gradient{background:linear-gradient(135deg,rgba(123,47,247,.25) 0%,rgba(100,40,200,.15) 50%,rgba(15,20,35,.95) 100%)}
.bp-card-pink .bp-card-gradient{background:linear-gradient(135deg,rgba(241,7,163,.25) 0%,rgba(200,10,140,.15) 50%,rgba(15,20,35,.95) 100%)}
.bp-card-orange .bp-card-gradient{background:linear-gradient(135deg,rgba(253,130,0,.25) 0%,rgba(220,110,0,.15) 50%,rgba(15,20,35,.95) 100%)}
.bp-card-green .bp-card-gradient{background:linear-gradient(135deg,rgba(0,245,160,.25) 0%,rgba(0,200,130,.15) 50%,rgba(15,20,35,.95) 100%)}
.bp-card-blue .bp-card-gradient{background:linear-gradient(135deg,rgba(0,120,255,.25) 0%,rgba(0,100,220,.15) 50%,rgba(15,20,35,.95) 100%)}

/* Card Shine Effect */
.bp-card-shine{position:absolute;top:-50%;left:-50%;width:200%;height:200%;background:linear-gradient(45deg,transparent 30%,rgba(255,255,255,.1) 50%,transparent 70%);opacity:0;transition:all .8s ease;pointer-events:none}

.bp-trend-card:hover .bp-card-shine{opacity:1;transform:translate(50%,50%)}

/* Hover State - INTENSE GRADIENTS */
.bp-card-cyan:hover .bp-card-gradient{background:linear-gradient(135deg,rgba(0,212,255,.4) 0%,rgba(0,180,220,.25) 50%,rgba(15,20,35,.9) 100%)}
.bp-card-purple:hover .bp-card-gradient{background:linear-gradient(135deg,rgba(123,47,247,.4) 0%,rgba(100,40,200,.25) 50%,rgba(15,20,35,.9) 100%)}
.bp-card-pink:hover .bp-card-gradient{background:linear-gradient(135deg,rgba(241,7,163,.4) 0%,rgba(200,10,140,.25) 50%,rgba(15,20,35,.9) 100%)}
.bp-card-orange:hover .bp-card-gradient{background:linear-gradient(135deg,rgba(253,130,0,.4) 0%,rgba(220,110,0,.25) 50%,rgba(15,20,35,.9) 100%)}
.bp-card-green:hover .bp-card-gradient{background:linear-gradient(135deg,rgba(0,245,160,.4) 0%,rgba(0,200,130,.25) 50%,rgba(15,20,35,.9) 100%)}
.bp-card-blue:hover .bp-card-gradient{background:linear-gradient(135deg,rgba(0,120,255,.4) 0%,rgba(0,100,220,.25) 50%,rgba(15,20,35,.9) 100%)}

.bp-trend-card:hover{transform:translateY(-16px) scale(1.02);box-shadow:0 40px 120px rgba(0,0,0,.5)}

/* Border Glow on Hover */
.bp-trend-card::before{content:'';position:absolute;inset:0;border-radius:32px;padding:2px;background:linear-gradient(135deg,transparent,rgba(255,255,255,.3),transparent);-webkit-mask:linear-gradient(#fff 0 0) content-box,linear-gradient(#fff 0 0);-webkit-mask-composite:xor;mask-composite:exclude;opacity:0;transition:opacity .6s ease;pointer-events:none}

.bp-card-cyan:hover::before{background:linear-gradient(135deg,rgba(0,212,255,.6),rgba(0,212,255,.2),rgba(0,212,255,.6));opacity:1}
.bp-card-purple:hover::before{background:linear-gradient(135deg,rgba(123,47,247,.6),rgba(123,47,247,.2),rgba(123,47,247,.6));opacity:1}
.bp-card-pink:hover::before{background:linear-gradient(135deg,rgba(241,7,163,.6),rgba(241,7,163,.2),rgba(241,7,163,.6));opacity:1}
.bp-card-orange:hover::before{background:linear-gradient(135deg,rgba(253,130,0,.6),rgba(253,130,0,.2),rgba(253,130,0,.6));opacity:1}
.bp-card-green:hover::before{background:linear-gradient(135deg,rgba(0,245,160,.6),rgba(0,245,160,.2),rgba(0,245,160,.6));opacity:1}
.bp-card-blue:hover::before{background:linear-gradient(135deg,rgba(0,120,255,.6),rgba(0,120,255,.2),rgba(0,120,255,.6));opacity:1}

/* Card Content */
.bp-card-content{position:relative;z-index:2;padding:50px 45px 55px;backdrop-filter:blur(10px)}

.bp-card-header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:35px}

.bp-card-number{font-size:5rem;font-weight:200;line-height:.8;opacity:.25;background:linear-gradient(135deg,#fff,rgba(255,255,255,.3));-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}

.bp-card-icon{color:rgba(255,255,255,.85);filter:drop-shadow(0 0 30px currentColor)}

.bp-card-cyan .bp-card-icon{color:rgba(0,212,255,.9)}
.bp-card-purple .bp-card-icon{color:rgba(123,47,247,.9)}
.bp-card-pink .bp-card-icon{color:rgba(241,7,163,.9)}
.bp-card-orange .bp-card-icon{color:rgba(253,130,0,.9)}
.bp-card-green .bp-card-icon{color:rgba(0,245,160,.9)}
.bp-card-blue .bp-card-icon{color:rgba(0,120,255,.9)}

.bp-card-title{font-size:2.2rem;font-weight:600;color:#fff;margin:0 0 25px;line-height:1.25;letter-spacing:-.01em}

.bp-card-text{font-size:1.1rem;font-weight:300;line-height:1.85;color:rgba(255,255,255,.8);margin:0 0 35px}

.bp-card-meta{display:flex;gap:12px;flex-wrap:wrap}

.bp-meta-tag{display:inline-block;padding:10px 22px;border-radius:30px;font-size:.9rem;font-weight:500;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.15);color:rgba(255,255,255,.95);letter-spacing:.02em;transition:all .3s ease}

.bp-trend-card:hover .bp-meta-tag{background:rgba(255,255,255,.15);border-color:rgba(255,255,255,.3)}

/* Footer CTA - ULTRA BRIGHT & GLOWING */
.bp-trends-footer{text-align:center;padding:100px 80px;background:linear-gradient(135deg,rgba(0,212,255,.1),rgba(123,47,247,.1),rgba(241,7,163,.1));border-radius:32px;border:1px solid rgba(255,255,255,.15);backdrop-filter:blur(30px);box-shadow:0 20px 60px rgba(0,0,0,.2)}

.bp-trends-footer-text{font-size:1.8rem;font-weight:300;color:rgba(255,255,255,.98);margin-bottom:50px;line-height:1.65;max-width:950px;margin-left:auto;margin-right:auto}

/* BRIGHT GLOWING CTA BUTTON */
.bp-trends-cta{display:inline-flex;align-items:center;gap:20px;font-size:1.35rem;font-weight:700;color:#fff;text-decoration:none;padding:28px 65px;border-radius:16px;background:linear-gradient(135deg,#00d4ff,#7b2ff7,#f107a3);border:none;transition:all .4s cubic-bezier(.34,1.56,.64,1);box-shadow:0 15px 50px rgba(0,212,255,.6),0 15px 50px rgba(241,7,163,.4),0 0 40px rgba(123,47,247,.5),0 0 0 2px rgba(255,255,255,.2) inset;position:relative;overflow:hidden;letter-spacing:.02em}

.bp-trends-cta::before{content:'';position:absolute;inset:0;background:linear-gradient(135deg,#00f5a0,#00d4ff,#7b2ff7);opacity:0;transition:opacity .4s ease}

.bp-trends-cta::after{content:'';position:absolute;top:-50%;left:-50%;width:200%;height:200%;background:linear-gradient(45deg,transparent,rgba(255,255,255,.3),transparent);transform:rotate(45deg);transition:all .8s ease}

.bp-trends-cta svg{transition:transform .4s cubic-bezier(.34,1.56,.64,1);position:relative;z-index:2}

.bp-trends-cta span{position:relative;z-index:2}

.bp-trends-cta:hover{gap:28px;transform:translateY(-8px) scale(1.03);box-shadow:0 30px 90px rgba(0,212,255,.8),0 30px 90px rgba(241,7,163,.6),0 0 60px rgba(123,47,247,.7),0 0 80px rgba(0,245,160,.4),0 0 0 3px rgba(255,255,255,.4) inset}

.bp-trends-cta:hover::before{opacity:1}

.bp-trends-cta:hover::after{left:100%}

.bp-trends-cta:hover svg{transform:translateX(8px) scale(1.1)}

/* Continuous Pulsing Glow */
@keyframes bp-trends-pulse{
  0%,100%{box-shadow:0 15px 50px rgba(0,212,255,.6),0 15px 50px rgba(241,7,163,.4),0 0 40px rgba(123,47,247,.5),0 0 0 2px rgba(255,255,255,.2) inset}
  50%{box-shadow:0 20px 70px rgba(0,212,255,.8),0 20px 70px rgba(241,7,163,.6),0 0 60px rgba(123,47,247,.7),0 0 40px rgba(0,245,160,.3),0 0 0 2px rgba(255,255,255,.3) inset}
}

.bp-trends-cta{animation:bp-trends-pulse 3s ease-in-out infinite}

/* Animations */
@keyframes bp-float-orb{
  0%,100%{transform:translate(0,0) scale(1)}
  33%{transform:translate(30px,-30px) scale(1.1)}
  66%{transform:translate(-30px,30px) scale(.9)}
}

@keyframes bp-fade-in{
  from{opacity:0;transform:translateY(40px)}
  to{opacity:1;transform:translateY(0)}
}

@keyframes bp-fade-up{
  from{opacity:0;transform:translateY(60px)}
  to{opacity:1;transform:translateY(0)}
}

