  padding:14px 18px!important;
  font-size:1rem!important;
  font-weight:400!important;
  color:rgba(255,255,255,.95)!important;
  background:rgba(255,255,255,.03)!important;
  border:1px solid rgba(255,255,255,.1)!important;
  border-radius:10px!important;
  outline:none!important;
  transition:all .3s ease!important;
  box-shadow:none!important;
  font-family:inherit!important;
  -webkit-appearance:none!important;
  -moz-appearance:none!important;
  appearance:none!important;
  line-height:1.5!important;
  box-sizing:border-box!important;
}

.bp-form-wrapper input:focus{
  background:rgba(255,255,255,.05)!important;
  border-color:rgba(0,212,255,.5)!important;
  box-shadow:0 0 0 3px rgba(0,212,255,.08)!important;
}

/* TWO COLUMN GRID FOR FIRST/LAST NAME */
.bp-form-wrapper .ff-el-group:has(input[name*="first" i]),
.bp-form-wrapper .ff-el-group:has(input[name*="last" i]){
  width:calc(50% - 10px)!important;
  display:inline-block!important;
  vertical-align:top!important;
}

.bp-form-wrapper .ff-el-group:has(input[name*="first" i]){
  margin-right:20px!important;
}

/* Textarea */
.bp-form-wrapper textarea,
.bp-form-wrapper .ff-el-form-control textarea{
  all:unset!important;
  display:block!important;
  width:100%!important;
  min-height:110px!important;
  padding:14px 18px!important;
  font-size:1rem!important;
  font-weight:400!important;
  color:rgba(255,255,255,.95)!important;
  background:rgba(255,255,255,.03)!important;
  border:1px solid rgba(255,255,255,.1)!important;
  border-radius:10px!important;
  outline:none!important;
  transition:all .3s ease!important;
  resize:vertical!important;
  box-shadow:none!important;
  font-family:inherit!important;
  -webkit-appearance:none!important;
  -moz-appearance:none!important;
  appearance:none!important;
  line-height:1.6!important;
  box-sizing:border-box!important;
}

.bp-form-wrapper textarea:focus{
  background:rgba(255,255,255,.05)!important;
  border-color:rgba(0,212,255,.5)!important;
  box-shadow:0 0 0 3px rgba(0,212,255,.08)!important;
}

/* SELECT */
.bp-form-wrapper select,
.bp-form-wrapper .ff-el-form-control select{
  all:unset!important;
  display:block!important;
  width:100%!important;
  padding:14px 40px 14px 18px!important;
  font-size:1rem!important;
  font-weight:400!important;
  color:rgba(255,255,255,.95)!important;
  background:rgba(255,255,255,.03)!important;
  border:1px solid rgba(255,255,255,.1)!important;
  border-radius:10px!important;
  outline:none!important;
  transition:all .3s ease!important;
  cursor:pointer!important;
  box-shadow:none!important;
  font-family:inherit!important;
  -webkit-appearance:none!important;
  -moz-appearance:none!important;
  appearance:none!important;
  background-image:url('data:image/svg+xml;charset=UTF-8,%3csvg width="12" height="8" viewBox="0 0 12 8" fill="none" xmlns="http://www.w3.org/2000/svg"%3e%3cpath d="M1 1L6 6L11 1" stroke="%2300d4ff" stroke-width="2" stroke-linecap="round"/%3e%3c/svg%3e')!important;
  background-position:right 16px center!important;
  background-size:12px 8px!important;
  background-repeat:no-repeat!important;
  line-height:1.5!important;
  box-sizing:border-box!important;
}

.bp-form-wrapper select:hover{
  border-color:rgba(255,255,255,.18)!important;
}

.bp-form-wrapper select:focus{
  background:rgba(255,255,255,.05)!important;
  border-color:rgba(0,212,255,.5)!important;
  box-shadow:0 0 0 3px rgba(0,212,255,.08)!important;
}

.bp-form-wrapper select option{
  all:unset!important;
  background:rgba(15,20,35,.98)!important;
  color:rgba(255,255,255,.95)!important;
  padding:12px 16px!important;
  font-size:1rem!important;
  display:block!important;
}

/* Radio & Checkbox */
.bp-form-wrapper input[type="radio"],
.bp-form-wrapper input[type="checkbox"]{
  all:unset!important;
  width:20px!important;
  height:20px!important;
  border:2px solid rgba(255,255,255,.2)!important;
  background:rgba(255,255,255,.02)!important;
  cursor:pointer!important;
  display:inline-block!important;
  position:relative!important;
  transition:all .3s ease!important;
  flex-shrink:0!important;
  vertical-align:middle!important;
}

.bp-form-wrapper input[type="radio"]{border-radius:50%!important}
.bp-form-wrapper input[type="checkbox"]{border-radius:5px!important}

.bp-form-wrapper input[type="radio"]:checked,
.bp-form-wrapper input[type="checkbox"]:checked{
  border-color:rgba(0,212,255,.8)!important;
  background:rgba(0,212,255,.15)!important;
}

.bp-form-wrapper input[type="radio"]:checked::after{
  content:''!important;
  position:absolute!important;
  top:50%!important;
  left:50%!important;
  width:8px!important;
  height:8px!important;
  background:rgba(0,212,255,1)!important;
  border-radius:50%!important;
  transform:translate(-50%,-50%)!important;
}

.bp-form-wrapper input[type="checkbox"]:checked::after{
  content:'✓'!important;
  position:absolute!important;
  top:50%!important;
  left:50%!important;
  color:rgba(0,212,255,1)!important;
  font-size:13px!important;
  font-weight:700!important;
  transform:translate(-50%,-50%)!important;
  line-height:1!important;
}

/* File Upload */
.bp-form-wrapper input[type="file"]{
  all:unset!important;
  display:block!important;
  width:100%!important;
  padding:14px 18px!important;
  font-size:.95rem!important;
  color:rgba(255,255,255,.7)!important;
  background:rgba(255,255,255,.02)!important;
  border:1px dashed rgba(255,255,255,.15)!important;
  border-radius:10px!important;
  cursor:pointer!important;
  transition:all .3s ease!important;
  box-sizing:border-box!important;
}

.bp-form-wrapper input[type="file"]:hover{
  border-color:rgba(0,212,255,.3)!important;
  color:rgba(255,255,255,.95)!important;
}

/* SUBMIT BUTTON - ABSOLUTE MAXIMUM NUCLEAR OVERRIDE */
.bp-form-wrapper button[type="submit"],
.bp-form-wrapper .ff-btn-submit,
.bp-form-wrapper .wpf-submit-container button,
.bp-form-wrapper input[type="submit"],
.bp-form-wrapper button.ff-btn,
.bp-form-wrapper .ff-btn-submit.ff-btn,
.bp-form-wrapper .ff_submit_btn_wrapper button,
.bp-form-wrapper .ff_submit_btn_wrapper .ff-btn,
.bp-form-wrapper .fluentform button[type="submit"],
.bp-form-wrapper .fluentform .ff-btn-submit,
.bp-form-wrapper form button[type="submit"],
.bp-form-wrapper button[type="submit"].ff-btn,
.bp-form-wrapper .ff-btn[type="submit"]{
  all:unset!important;
  display:block!important;
  width:100%!important;
  padding:18px 40px!important;
  font-size:1.1rem!important;
  font-weight:600!important;
  color:#ffffff!important;
  text-align:center!important;
  background:linear-gradient(135deg,#00d4ff 0%,#f107a3 100%)!important;
  border:none!important;
  border-radius:12px!important;
  cursor:pointer!important;
  transition:all .3s ease!important;
  text-transform:none!important;
  letter-spacing:.02em!important;
  box-shadow:0 15px 40px rgba(0,212,255,.25)!important;
  margin:35px 0 0 0!important;
  font-family:inherit!important;
  -webkit-appearance:none!important;
  -moz-appearance:none!important;
  appearance:none!important;
  line-height:1.4!important;
  position:relative!important;
  overflow:hidden!important;
  text-decoration:none!important;
  background-color:transparent!important;
  background-image:linear-gradient(135deg,#00d4ff 0%,#f107a3 100%)!important;
  box-sizing:border-box!important;
}

/* HOVER STATE - NUCLEAR OVERRIDE */
.bp-form-wrapper button[type="submit"]:hover,
.bp-form-wrapper .ff-btn-submit:hover,
.bp-form-wrapper input[type="submit"]:hover,
.bp-form-wrapper button.ff-btn:hover,
.bp-form-wrapper .fluentform button[type="submit"]:hover,
.bp-form-wrapper button[type="submit"]:hover.ff-btn,
.bp-form-wrapper .ff-btn[type="submit"]:hover{
  background:linear-gradient(135deg,#00b8e6 0%,#d90790 100%)!important;
  background-color:transparent!important;
  background-image:linear-gradient(135deg,#00b8e6 0%,#d90790 100%)!important;
  transform:translateY(-3px)!important;
  box-shadow:0 25px 60px rgba(0,212,255,.4)!important;
  color:#ffffff!important;
  border:none!important;
  opacity:1!important;
}

/* ACTIVE STATE */
.bp-form-wrapper button[type="submit"]:active,
.bp-form-wrapper .ff-btn-submit:active{
  transform:translateY(-1px)!important;
  box-shadow:0 15px 40px rgba(0,212,255,.3)!important;
}

/* Remove Pseudo Elements */
.bp-form-wrapper button[type="submit"]::before,
.bp-form-wrapper button[type="submit"]::after,
.bp-form-wrapper .ff-btn-submit::before,
.bp-form-wrapper .ff-btn-submit::after{
  display:none!important;
  content:none!important;
  background:none!important;
}

/* Placeholder */
.bp-form-wrapper input::placeholder,
.bp-form-wrapper textarea::placeholder{
  color:rgba(255,255,255,.3)!important;
  opacity:1!important;
}

/* Form Field Spacing */
.bp-form-wrapper .ff-el-group,
.bp-form-wrapper .ff-el-input--content{
  all:unset!important;
  display:block!important;
  margin:0 0 24px 0!important;
  width:100%!important;
}

/* Error & Success */
.bp-form-wrapper .error,
.bp-form-wrapper .text-danger{
  color:rgba(255,100,100,1)!important;
  font-size:.8rem!important;
  margin:8px 0 0 0!important;
}

.bp-form-wrapper .ff-message-success{
  background:rgba(0,245,160,.1)!important;
  border:1px solid rgba(0,245,160,.3)!important;
  color:rgba(255,255,255,.95)!important;
  padding:18px!important;
  border-radius:10px!important;
  margin:20px 0!important;
}

/* Required */
.bp-form-wrapper .ff_required_field{
  color:rgba(241,7,163,1)!important;
}

/* Animations */
@keyframes bp-orb-float{
  0%,100%{transform:translate(0,0)}
  50%{transform:translate(30px,-30px)}
}

@keyframes bp-pulse-ring{
  0%,100%{transform:scale(1);opacity:.3}
  50%{transform:scale(1.1);opacity:.6}
}

@keyframes bp-line-grow{
  0%,100%{height:60px;opacity:.3}
  50%{height:90px;opacity:.6}
}

@keyframes bp-fade-in{
  from{opacity:0;transform:translateY(40px)}
  to{opacity:1;transform:translateY(0)}
}

@keyframes bp-fade-up{
  from{opacity:0;transform:translateY(50px)}
  to{opacity:1;transform:translateY(0)}
}

